nuBrowseStyleBadge(3);

// colours by value: exact values as a map …
nuBrowseStyleBadge(4, {open: '#cfe2ff', closed: {bg: '#d1e7dd', color: '#0f5132', icon: 'check'}});

// … or rules (the first that matches wins)
nuBrowseStyleBadge(5, [
  {equals: 'abc', bg: '#d4edda', color: '#155724'},
  {contains: 'urgent', bg: '#FAA'},
  {startsWith: 'ERR', class: 'text-bg-danger'},
  {regex: /^\d{4}$/, bg: '#e2e3e5'},
  {test: (v, row) => Number(v) > 100, bg: '#fff3cd', title: 'over 100'},
  {equals: '1', label: 'Active', icon: 'check-circle', bg: '#d1e7dd'},
  {equals: '-', badge: false},
  {default: true, bg: '#eee'}
], {ignoreCase: true});

// a column that holds a colour code: the badge is painted in it
nuBrowseStyleBadge(6, [{default: true, bg: '$value'}]);

