function nuOnPromptClose(value, ok) {
    if (ok) nuSetValue('inv_reason', value);
}

function nuOnPageLoad(page, info) {
    if (page === 'home') document.title = 'Start';
    if (page === 'form' && info.form === 'customer') nuSetTitle('Customers');
}

function nuOnFileUploadComplete(target, objectId, result, message) {
    nuMessage([message]);
}

function nuBeforeSave() {
    if (nuGetValue('inv_total') < 0) { nuMessage('Total below zero.'); return false; }
    return true;
}

function nuOnLookupPopulated(id, prefix, data) {
    if (id === 'inv_customer_id') nuSetValue('inv_city', data[2]);
}

function nuOnSelectTab(tab) {
    return nuIsSaved();   // stay until saved
}

function nuSelectBrowse(event, element) {
    const primaryKey = $(element).attr('data-nu-primary-key');
    nuForm(nuFormId(), primaryKey, '', '', '2');
}

function nuOnSetCalendarOptions(id, options) {
    if (id === 'inv_due') options.minDate = new Date();
    return options;
}

function nuOnRawValueFormatted(id, rawValue, format) {
    return id === 'inv_rate' ? rawValue / 100 : rawValue;
}

function nuOnSetSelect2Options(id, options) {
    options.maxOptions = 500;
    return options;
}

function nuOnPopupOpenedGlobal(formId, recordId) {
    console.log('popup', formId, recordId);
}

function nuOnDisableGlobal(id, component) {
    return id !== 'inv_notes';   // notes stay editable
}
